sys_script_include.script:
SubTemplateFlow.prototype = {
    initialize: function() {},

    // Button visibility
    canRetrieveFields: function(subTemplate) {
        return subTemplate.getValue('state') == 'draft';
    },

    canValidate: function(subTemplate) {
        return subTemplate.getValue('state') == 'mapping';
    },

    canComplete: function(subTemplate) {
        return subTemplate.getValue('state') == 'validated';
    },

    canEditAgain: function(subTemplate) {
        return subTemplate.getValue('state') != 'draft';
    },

    // Button actions
    retrieveFields: function(subTemplate) {
        var html = subTemplate.getValue('html_template');

        if (!html) {
            return {
                success: false,
                message: 'Please add SubTemplate HTML before retrieving fields.'
            };
        }

        var tableName = subTemplate.getValue('table');

        if (!tableName) {
            return {
                success: false,
                message: 'Please select a table before retrieving fields.'
            };
        }

        var fieldUtil = new x_2162040_documate.fieldMappingUtils();
        fieldUtil.subtempRetrive(subTemplate);

        subTemplate.setValue('state', 'mapping');
        subTemplate.update();

        return {
            success: true,
            message: 'Sub Template fields retrieved successfully. State moved to Mapping.'
        };
    },

    validateSubTemplate: function(subTemplate) {
        var errors = [];

        //mapping
        var fm = new GlideRecord('x_2162040_documate_field_mapping');
       fm.addQuery('mapping_context', 'sub_template');
        fm.addQuery('sub_template', subTemplate.getUniqueValue());
        fm.query();

        var fmcnt = 0;
        while (fm.next()) {
            if ((fm.getValue('evaluate_value_using_script') == true && gs.nil(fm.getValue('script_value'))) || (fm.getValue('evaluate_value_using_script') == false && gs.nil(fm.getValue('field')))) {
                fmcnt++;
            }
        }

        if (fmcnt > 0) {
            errors.push('Field Mapping of ' + fmcnt + ' Sub Template Fields is Required.');
        }

        if (errors.length > 0) {
            return {
                success: false,
                message: errors.join('<br/>')
            };
        }

        subTemplate.setValue('state', 'validated');
        subTemplate.update();

        return {
            success: true,
            message: 'Sub Template validated successfully.'
        };
    },


    completeSubTemplate: function(subTemplate) {
        if (subTemplate.getValue('state') != 'validated') {
            return {
                success: false,
                message: 'Only validated Sub Templates can be completed.'
            };
        }

        subTemplate.setValue('state', 'complete');
        subTemplate.update();

        return {
            success: true,
            message: 'Sub Template marked as Complete.'
        };
    },

    editAgain: function(subTemplate) {
        subTemplate.setValue('state', 'draft');
        subTemplate.update();

        return {
            success: true,
            message: 'Sub Template moved back to Draft.'
        };
    },

    type: 'SubTemplateFlow'
};
